INSERT INTO knowledge_documents ("id", "title", "kind", "places", "keywords", "body", "source_url", "updated_at") VALUES ('heritage_pyeongneung', '평능역 (폐역)', 'heritage', '["heritage_pyeongneung"]', '["평능역","평능","폐역"]', '평능역은 1962년에 생겼다가 1969년에 폐지된 역이에요. 지금은 흔적이 남아 있지 않아요.
INSERT INTO knowledge_documents ("id", "title", "kind", "places", "keywords", "body", "source_url", "updated_at") VALUES ('poi_bukpyeong_market', '북평민속시장', 'poi', '["poi_bukpyeong_market"]', '["북평민속시장","북평장","북평시장","오일장","장날","재래시장","장터","전통시장"]', '북평민속시장은 날짜 끝자리가 3과 8인 날에 열리는 오일장이에요. 1796년에 시작된 장으로, 강원도에서 가장 크고 전국 3대 오일장으로 꼽혀요.', NULL, '2026-11-19T00:00:00+00:00');
INSERT INTO knowledge_documents ("id", "title", "kind", "places", "keywords", "body", "source_url", "updated_at") VALUES ('poi_cheongok_cave', '천곡황금박쥐동굴', 'poi', '["poi_cheongok_cave"]', '["천곡동굴","천곡황금박쥐동굴","황금박쥐동굴","석회석 동굴"]', '천곡황금박쥐동굴은 도심에 있는 유일한 천연 석회석 동굴이에요. 4~5억 년 전에 만들어졌고, 총 길이 1510m 가운데 810m를 관람할 수 있어요.
INSERT INTO knowledge_documents ("id", "title", "kind", "places", "keywords", "body", "source_url", "updated_at") VALUES ('poi_chotdaebawi', '촛대바위', 'poi', '["poi_chotdaebawi","station_chuam"]', '["촛대바위","추암해변","해암정","출렁다리","일출"]', '촛대바위는 추암역 근처에 있어요. 동해시와 삼척시 경계에 있는 일출 명소이고, 애국가 첫 소절의 배경 영상에 나온 곳이에요.
INSERT INTO knowledge_documents ("id", "title", "kind", "places", "keywords", "body", "source_url", "updated_at") VALUES ('poi_dojjebigol', '도째비골 스카이밸리', 'poi', '["poi_dojjebigol"]', '["도째비골","스카이밸리","해랑전망대"]', '도째비골 스카이밸리는 동해시의 관광지예요. 묵호등대, 논골담길과 같은 묵호권역에 있어요.
INSERT INTO knowledge_documents ("id", "title", "kind", "places", "keywords", "body", "source_url", "updated_at") VALUES ('poi_mangsang_beach', '망상해수욕장', 'poi', '["poi_mangsang_beach"]', '["망상해수욕장"]', '망상해수욕장은 동해시의 관광지예요. 넓은 백사장과 울창한 송림, 맑은 바닷물이 있어요.
INSERT INTO knowledge_documents ("id", "title", "kind", "places", "keywords", "body", "source_url", "updated_at") VALUES ('poi_nongoldam', '논골담길', 'poi', '["poi_nongoldam","station_mukho"]', '["논골담길","논골담","묵호등대","벽화"]', '논골담길은 묵호역 근처에 있어요. 묵호항에서 묵호등대까지 이어지는 비탈 골목이고, 담벼락에는 주민들의 생활과 이야기를 담은 벽화가 있어요.
INSERT INTO knowledge_documents ("id", "title", "kind", "places", "keywords", "body", "source_url", "updated_at") VALUES ('rail_2031_changes', '2031년 고속화·지하화로 사라질 풍경', 'rail', '[]', '["2031","고속화","지하화","해안 선로","사라질"]', '2031년 고속화·지하화 사업으로 지금의 해안 선로 풍경이 사라질 예정이에요.', NULL, '2026-11-19T00:00:00+00:00');
INSERT INTO knowledge_documents ("id", "title", "kind", "places", "keywords", "body", "source_url", "updated_at") VALUES ('rail_lines', '동해시를 지나는 노선', 'rail', '[]', '["노선","영동선","삼척선","북평선","묵호항선"]', '동해시 철도와 관련된 노선으로 영동선, 삼척선, 북평선, 묵호항선이 있어요.', NULL, '2026-11-19T00:00:00+00:00');
INSERT INTO knowledge_documents ("id", "title", "kind", "places", "keywords", "body", "source_url", "updated_at") VALUES ('rail_train_types', '열차 종류 구분', 'rail', '["station_donghae"]', '["차종","열차 종류","KTX-이음","ITX-마음","누리로","무궁화호","무궁화","화물열차"]', '동해역에는 KTX-이음, ITX-마음, 누리로, 무궁화호 같은 여객열차와 화물열차가 지나가요. 열차 종류 이름은 TIDS 표기를 따라요.
INSERT INTO knowledge_documents ("id", "title", "kind", "places", "keywords", "body", "source_url", "updated_at") VALUES ('safety_hapyeong_crossing', '하평 건널목 사례', 'safety', '[]', '["하평","하평건널목","하평 건널목"]', '하평 건널목은 2026년 2월 관광객이 머무는 일로 폐쇄됐다가, 안전요원을 두는 조건으로 다시 열렸어요.', NULL, '2026-11-19T00:00:00+00:00');
INSERT INTO knowledge_documents ("id", "title", "kind", "places", "keywords", "body", "source_url", "updated_at") VALUES ('safety_passing_station', '통과역 규칙', 'safety', '[]', '["통과역","통과","정차"]', '열차가 서지 않고 지나가는 역에서는 타고 내릴 수 없어요. 지나가는 열차를 보는 것만 가능해요.', NULL, '2026-11-19T00:00:00+00:00');
INSERT INTO knowledge_documents ("id", "title", "kind", "places", "keywords", "body", "source_url", "updated_at") VALUES ('safety_track_crossing', '선로·건널목 안전 원칙', 'safety', '[]', '["건널목","선로","차단기","철길","철로"]', '건널목 안, 차단기 안쪽, 선로 부지에 들어가거나 그 안에서 촬영하는 건 권하지 않아요. 역 맞이방이나 승강장처럼 공개된 장소에서 열차를 보는 방법을 찾아 주세요.', NULL, '2026-11-19T00:00:00+00:00');
INSERT INTO knowledge_documents ("id", "title", "kind", "places", "keywords", "body", "source_url", "updated_at") VALUES ('station_chuam', '추암역', 'station', '["station_chuam","poi_chotdaebawi"]', '["추암역","추암","바다열차","삼척선"]', '추암역은 삼척선의 역이에요. 근처에 촛대바위가 있어요.
INSERT INTO knowledge_documents ("id", "title", "kind", "places", "keywords", "body", "source_url", "updated_at") VALUES ('station_donghae', '동해역', 'station', '["station_donghae"]', '["동해역","북평역","분기역","철도기념비"]', '동해역은 KTX-이음, ITX-마음, 누리로, 무궁화와 화물열차가 한 역을 지나는 분기역이에요. 1940년 북평역으로 문을 열었어요.
INSERT INTO knowledge_documents ("id", "title", "kind", "places", "keywords", "body", "source_url", "updated_at") VALUES ('station_mangsang', '망상역', 'station', '["station_mangsang"]', '["망상역"]', '망상역은 2011년부터 평소에는 여객열차가 서지 않아요. 열차가 지나가는 모습은 관찰만 할 수 있고 타고 내릴 수는 없어요.
INSERT INTO knowledge_documents ("id", "title", "kind", "places", "keywords", "body", "source_url", "updated_at") VALUES ('station_mangsang_beach', '망상해수욕장 임시승강장', 'station', '["station_mangsang_beach","poi_mangsang_beach"]', '["임시승강장","망상해수욕장역"]', '망상해수욕장 임시승강장이에요. 운영 시기는 아직 확인된 정보가 없어요.', NULL, '2026-11-19T00:00:00+00:00');
INSERT INTO knowledge_documents ("id", "title", "kind", "places", "keywords", "body", "source_url", "updated_at") VALUES ('station_mukho', '묵호역', 'station', '["station_mukho","poi_nongoldam"]', '["묵호역","묵호"]', '묵호역 근처에 논골담길이 있어요.', NULL, '2026-11-19T00:00:00+00:00');
INSERT INTO knowledge_documents ("id", "title", "kind", "places", "keywords", "body", "source_url", "updated_at") VALUES ('station_mukhohang', '묵호항역', 'station', '["station_mukhohang"]', '["묵호항역","묵호항선"]', '묵호항역은 여객열차가 서지 않는 화물역이에요. 화물열차 시각은 공식 데이터가 없어서 안내하지 못해요.', NULL, '2026-11-19T00:00:00+00:00');
INSERT INTO knowledge_documents ("id", "title", "kind", "places", "keywords", "body", "source_url", "updated_at") VALUES ('station_samhwa', '삼화역', 'station', '["station_samhwa"]', '["삼화역","삼화"]', '삼화역은 여객열차가 서지 않는 화물역이에요. 화물열차 시각은 공식 데이터가 없어서 안내하지 못해요.', NULL, '2026-11-19T00:00:00+00:00');
